import{c as n,Q as e,j as i,m as r}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Quantum Machine Learning for Industrial Applications","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.14822","title":"Quantum Machine Learning for Industrial Applications","archived_date":"2026-07-25T00:00:00.000Z","arxiv_id":2606.14822,"authors":["Léo Monbroussou"],"domain":"quantum-classical-machine-learning","published_date":"2026-06-12T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-25-quantum-ml-industrial-applications-2606-14822.md","filePath":"research/papers/2026-07-25-quantum-ml-industrial-applications-2606-14822.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-07-25-quantum-ml-industrial-applications-2606-14822.md"};function s(o,a,l,u,p,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="quantum-machine-learning-for-industrial-applications" tabindex="-1">Quantum Machine Learning for Industrial Applications <a class="header-anchor" href="#quantum-machine-learning-for-industrial-applications" aria-label="Permalink to &quot;Quantum Machine Learning for Industrial Applications&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>本文（Sorbonne 大學 LIP6 實驗室博士論文）探討變分量子電路的可訓練性、表達力與抗古典模擬性。核心貢獻包含 Hamming-weight preserving 電路的理論分析、subspace-preserving QML 演算法（含光子電路與量子卷積網路，模擬古典 ML 子程序但具多項式量子優勢）、以及將變分量子電路視為量子傅立葉模型的分析架構。目標是建立量子模型可證明優於古典對應物的具體條件，推進近未來量子技術的實務應用。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>變分量子電路的可證明優勢條件研究，與 workspace 現有版圖無內容重疊；核心關鍵詞於三個既有集合反向 grep 命中皆為 0，與同批收錄的 2607.10563（議程）、2606.16090（理論）共同構成本次 quantum-classical-machine-learning 領域的工程層證據。</p>',5)])])}const h=n(t,[["render",s]]);export{m as __pageData,h as default};
